import urllib.parse

def is_valid_subdomain(target: str, domain: str) -> bool:
    parsed = urllib.parse.urlparse(target)
    netloc = parsed.netloc
    if not netloc:
        return False
    # Ensure the domain is fully qualified (e.g., 'example.com' becomes 'example.com')
    domain = domain if domain.startswith('http') else 'https://' + domain
    return netloc == domain or netloc.endswith('.' + domain.split('.')[-2] + '.' + domain.split('.')[-1])
